#include <stacktrace>
#include <functional>
#include <string>
#include <sstream>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    auto trace = std::stacktrace::current();
    std::stacktrace copy;
    copy = trace;
    assert(copy == trace);
    auto allocator = trace.get_allocator();
    (void)allocator;
    copy.swap(trace);
    std::swap(copy, trace);
    (void)std::hash<std::stacktrace>{}(trace);
    if (!trace.empty()) {
        std::stacktrace_entry entry = trace.at(0), assigned;
        assigned = entry;
        assert(assigned == entry && static_cast<bool>(entry));
        assert(trace[0] == entry);
        (void)entry.native_handle();
        (void)entry.description();
        (void)entry.source_file();
        (void)entry.source_line();
        assert(std::hash<std::stacktrace_entry>{}(assigned) ==
            std::hash<std::stacktrace_entry>{}(entry));
    }
    // Stack collection and source-symbol availability depend on the implementation.
}
